def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    rolling_max_list = []
    window_size = 1

    for i in range(len(numbers) - window_size + 1):
        max_in_window = max(numbers[i:i+window_size])
        rolling_max_list.append(max_in_window)

    return rolling_max_list
